from pathlib import Path
import json,re,html
P=Path(__file__).parent
rows=json.loads((P/'catalog/providers.json').read_text());stats=json.loads((P/'catalog/stats.json').read_text());sources=json.loads((P/'research/sources.json').read_text());caps=json.loads((P/'catalog/capabilities.json').read_text())
# Accessible office guide.
from docx import Document
from docx.shared import Inches,Pt,RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
doc=Document();sec=doc.sections[0];sec.top_margin=Inches(.7);sec.bottom_margin=Inches(.65);sec.left_margin=sec.right_margin=Inches(.75)
style=doc.styles['Normal'];style.font.name='Calibri';style.font.size=Pt(10);style.paragraph_format.space_after=Pt(6)
for name in ['Title','Heading 1','Heading 2','Heading 3']:
 doc.styles[name].font.color.rgb=RGBColor.from_string('16324F')
header=sec.header.paragraphs[0];header.text='PROVIDER ATLAS   /   KYC · CDD · AML';header.style='Caption'
footer=sec.footer.paragraphs[0];footer.text='Design proposal • Offline starter • 15 October 2026                                      '
fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
lines=(P/'docs/Architecture_and_Integration_Guide.md').read_text().splitlines();in_code=False;table_lines=[]
def plain(t):return re.sub(r'\*\*|`','',t)
def flush_table():
 if not table_lines:return
 vals=[[plain(x.strip()) for x in ln.strip().strip('|').split('|')] for ln in table_lines if not re.match(r'^\|[\s:|\-]+\|$',ln)]
 if not vals:return
 t=doc.add_table(rows=1,cols=len(vals[0]));t.style='Light Shading Accent 1'
 for j,v in enumerate(vals[0]):t.rows[0].cells[j].text=v
 for row in vals[1:]:
  cells=t.add_row().cells
  for j,v in enumerate(row[:len(cells)]):cells[j].text=v
 table_lines.clear()
for line in lines:
 if line.startswith('|') and not in_code:table_lines.append(line);continue
 flush_table()
 if line.startswith('```'):in_code=not in_code;continue
 if not line.strip():continue
 if in_code:
  p=doc.add_paragraph();r=p.add_run(line);r.font.name='Consolas';r.font.size=Pt(7.5);p.paragraph_format.space_after=Pt(0);continue
 if line.startswith('# '):doc.add_heading(plain(line[2:]),0)
 elif line.startswith('## '):doc.add_heading(plain(line[3:]),1)
 elif line.startswith('### '):doc.add_heading(plain(line[4:]),2)
 elif line.startswith('- '):doc.add_paragraph(plain(line[2:]),style='List Bullet')
 else:doc.add_paragraph(plain(line))
flush_table();doc.add_page_break();doc.add_heading('Appendix: inspected sources',1)
for s in sources:
 doc.add_heading(s['source_id']+' · '+s['provider'],2)
 doc.add_paragraph(s['url']);doc.add_paragraph(s['evidence_type']+' · '+s['observations'])
doc.save(P/'Architecture_and_Integration_Guide.docx')
# Self-contained explorer. No remote scripts, fonts, images or requests.
PAGE='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KYC Provider Atlas</title><style>
:root{--ink:#173149;--muted:#526477;--blue:#106a78;--paper:#f2f5f7;--line:#dae3e9}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:14px/1.5 system-ui,-apple-system,sans-serif}header{padding:36px 5% 30px;background:#142d43;color:#fff}header small{letter-spacing:.16em;color:#8de0d1;font-weight:700}h1{font-size:38px;line-height:1.15;margin:12px 0}header p{max-width:850px;color:#cbdae6;font-size:16px}nav{display:flex;gap:8px;margin-top:24px;flex-wrap:wrap}button{font:inherit;cursor:pointer}nav button{border:1px solid #557086;color:#e9f2f7;background:transparent;padding:9px 18px;border-radius:6px}nav button.active{background:#a9e9da;color:#16324f;border-color:#a9e9da}main{padding:26px 5% 50px;max-width:1800px;margin:auto}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.metric,.panel{background:white;border:1px solid var(--line);border-radius:9px;padding:20px}.metric strong{font-size:30px;display:block}.metric span{color:var(--muted);font-size:12px}.notice{background:#fff5de;border-left:4px solid #c08a23;padding:15px 18px;margin:20px 0;color:#69501e}.subtle{color:var(--muted)}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}input,select{background:white;border:1px solid #becdd8;border-radius:6px;padding:11px;font:inherit;color:var(--ink)}input{min-width:280px;flex:1}table{width:100%;border-collapse:collapse;background:white}th{text-align:left;background:#e7eef2;font-size:11px;letter-spacing:.06em;text-transform:uppercase;padding:13px}td{padding:13px;border-bottom:1px solid #e5edf1;vertical-align:top}.tablewrap{border:1px solid var(--line);border-radius:8px;overflow:auto}tr.clickable:hover{background:#f0f9f8;cursor:pointer}.tag{display:inline-block;padding:3px 8px;border-radius:4px;background:#edf2f6;font-size:11px;margin:2px}.good{color:#126b57;background:#e2f4ed}.warn{color:#7c5c13;background:#fcf0d3}.bad{color:#8c3030;background:#fde8e8}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel h2{font-size:20px;margin-top:0}.panel h3{font-size:16px}.flow{display:flex;gap:10px;flex-wrap:wrap}.step{padding:14px;background:#e9f2f4;border-radius:6px;flex:1;min-width:130px}.code{font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;background:#142d43;color:#d3eee8;padding:20px;border-radius:7px;overflow:auto}.hidden{display:none!important}#detail{position:fixed;inset:0;background:#142d4380;z-index:3;display:flex;justify-content:flex-end}#detail article{width:min(680px,95vw);background:white;height:100%;overflow:auto;padding:30px;box-shadow:-5px 0 35px #0002}#close{float:right;padding:8px 12px;border:1px solid #ccd8df;border-radius:5px;background:#f2f5f7}.kv{display:grid;grid-template-columns:150px 1fr;gap:12px;border-bottom:1px solid #e6ecf0;padding:10px 0;word-break:break-word}.kv b{color:var(--muted);font-size:12px}.count{font-weight:600;margin:12px 0}.source{padding:15px 0;border-bottom:1px solid var(--line)}a{color:#106a78;word-break:break-word}.foot{font-size:12px;color:var(--muted);margin-top:16px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}h1{font-size:29px}main{padding:20px}header{padding:28px 20px}.kv{grid-template-columns:110px 1fr}}
</style></head><body><header><small>DATA & INTEGRATION REFERENCE / 2026.10</small><h1>KYC Provider Atlas</h1><p>A global discovery inventory and a bank-owned host model for identity, business verification, screening, monitoring and connection resolution.</p><nav><button class="active" data-tab="catalog">Provider catalog</button><button data-tab="model">Host model</button><button data-tab="adapters">Adapters</button><button data-tab="evidence">Evidence & limits</button></nav></header><main><section class="metrics"><div class="metric"><strong>376</strong><span>catalog records · not unique active vendors</span></div><div class="metric"><strong>824</strong><span>proposed capability bindings</span></div><div class="metric"><strong>37 / 18</strong><span>capabilities / typed result families</span></div><div class="metric"><strong>9</strong><span>offline fixture normalizers</span></div><div class="metric"><strong>0</strong><span>live integrations validated</span></div></section><div class="notice"><b>Broad inventory, not a certified exhaustive list.</b> Only 18 records have separately reviewed detailed public material; 358 remain candidates. The 368 URL metadata checks are a separate availability audit, not API or capability verification. All connections are disabled.</div>
<section id="catalog" class="tab"><div class="tools"><input id="search" type="search" placeholder="Search provider, region, capability or alias…" aria-label="Search catalog"><select id="category" aria-label="Category"><option value="">All 14 categories</option></select><select id="evidenceFilter" aria-label="Evidence"><option value="">All evidence levels</option><option value="public_docs_reviewed">Public docs reviewed</option><option value="public_material_reviewed">Other public material reviewed</option><option value="candidate_unverified">Candidate / unverified</option></select></div><div id="count" class="count"></div><div class="tablewrap"><table><thead><tr><th>Provider / service</th><th>Category / orientation</th><th>Proposed capability family</th><th>Evidence</th><th>Adapter</th></tr></thead><tbody id="providerRows"></tbody></table></div><p class="foot">Select a row for source IDs, aliases, HTTP metadata, mapping readiness and access limitations. Market orientation is not a contracted country-coverage matrix.</p></section>
<section id="model" class="tab hidden"><h2>One host contract. Explicit meaning.</h2><div class="flow"><div class="step"><b>1. Host request</b><br>Subject · purpose · policy · consent</div><div class="step"><b>2. Connection resolver</b><br>Entitlement · country · residency</div><div class="step"><b>3. Adapter</b><br>Native request ↔ canonical result</div><div class="step"><b>4. Bank consumers</b><br>Graph · cases · policy · audit</div></div><div class="columns" style="margin-top:20px"><div class="panel"><h2>Canonical envelope</h2><div class="code">HostResult\n ├ schema_version / result_id / request_id / tenant_id\n ├ subject_entity_id / capability\n ├ provider: version, original status, decision origin\n ├ execution: technical lifecycle\n ├ assessment: check outcome ≠ bank decision\n ├ coverage: checked / missing / unknown\n ├ entities / relationships / assertions\n ├ evidence: provenance, rights, classification\n ├ result: one typed capability result\n ├ errors / warnings\n └ raw_payload: restricted vault reference + digest</div><h3>Connection resolution ≠ entity resolution</h3><p>Routing selects an approved provider. Entity resolution evaluates links between source records. An exact identifier produces a possible connection in the starter, never an automatic merge.</p></div><div class="panel"><h2>Consumer safeguards</h2><ul><li>HTTP success is not completed verification.</li><li>Completed workflow is not approved customer.</li><li>Screening candidate is not a true match.</li><li>Null / missing is not clear or zero.</li><li>Parent company records are not natural-person UBO proof.</li><li>Shared address / device is not ownership or identity.</li><li>Provider scores stay on their native scales.</li><li>Bank decisions require policy and actor provenance.</li></ul><h3>Schema files</h3><p>request.schema.json · host.schema.json · adapter.schema.json · event.schema.json · openapi.yaml</p><p class="subtle">Draft 2020-12 schemas. Proposed bank-owned model, not an asserted industry standard. Examples for every capability are included in the bundle.</p></div></div><h2>37 canonical capabilities</h2><div class="tablewrap"><table><thead><tr><th>Capability</th><th>Typed result family</th></tr></thead><tbody id="capRows"></tbody></table></div></section>
<section id="adapters" class="tab hidden"><h2>Representative adapter pack</h2><p class="subtle">Synthetic fixture subsets, not live clients. Six non-executable request plans are also included. No transport, signatures, secrets or vendor sandbox testing is supplied.</p><div class="tablewrap"><table><thead><tr><th>Adapter</th><th>Native subset</th><th>Critical interpretation</th></tr></thead><tbody id="adapterRows"></tbody></table></div><div class="columns" style="margin-top:20px"><div class="panel"><h2>Run offline</h2><div class="code">python -m pip install -r requirements.txt\npython -m unittest discover -s tests -v\npython adapters/runtime.py sumsub \\\n  examples/native/sumsub.json --out normalized.json</div><p>32 tests cover schemas, capability examples, mapping semantics, partial data, drift, namespaces, consent prerequisites and quarantined routing.</p></div><div class="panel"><h2>Promotion gates</h2><ol><li>Get authorized native contracts and entitlements.</li><li>Pin product, API, region and adapter version.</li><li>Implement secure transport and verified webhooks.</li><li>Test positive, negative, empty, partial, drift and change cases.</li><li>Run vendor sandbox and institution acceptance.</li><li>Enable a controlled, monitored canary.</li></ol><p class="subtle">All other proposed bindings have null native paths and disabled routes. Do not invent endpoints from catalog names.</p></div></div></section>
<section id="evidence" class="tab hidden"><div class="columns" style="margin-top:20px"><div class="panel"><h2>Evidence ladder</h2><p><span class="tag good">10 public-docs records</span> Documented fields inspected for representative contracts; only nine implemented.</p><p><span class="tag good">8 other reviewed records</span> Product pages or relevant search excerpts reviewed; not full payload verification.</p><p><span class="tag warn">358 candidate records</span> Discovery scope and proposed capabilities require individual validation.</p><p>Separately: 368 URL retrieval attempts; 322 HTTP 2xx. A homepage's title or marketing description does not prove data coverage, current ownership, a public API or bank adoption.</p></div><div class="panel"><h2>Scope and security limits</h2><p>Includes registry/network families, legacy aliases, managed services and adjacent fraud components. This is not a count of independent vendors and not a regulatory certification.</p><p><b>Finantier historical domain is quarantined:</b> reference content was unrelated gambling. Do not use it to connect. Other reference errors do not establish business closure.</p><p>Restricted BOI, identity, bureau and law-enforcement sources require authorized access. Catalog URLs are not executable API base URLs. Country and residency allowlists are empty until validated.</p></div></div><div class="panel" style="margin-top:20px"><h2>Inspected documentation and discovery sources</h2><div id="sourceList"></div></div></section></main><div id="detail" class="hidden" role="dialog" aria-modal="true" aria-label="Provider details"><article><button id="close">Close ✕</button><h2 id="detailTitle"></h2><div id="detailBody"></div></article></div><script>
const providers=__PROVIDERS__,caps=__CAPS__,sources=__SOURCES__;
const $=id=>document.getElementById(id);const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
[...new Set(providers.map(p=>p.category))].sort().forEach(c=>{const o=el('option',c);o.value=c;$('category').append(o)});
function evidenceTag(value){return el('span',value.replaceAll('_',' '),'tag '+(value==='candidate_unverified'?'warn':'good'))}
function render(){const query=$('search').value.toLowerCase(),category=$('category').value,evidence=$('evidenceFilter').value;const found=providers.filter(p=>(!category||p.category===category)&&(!evidence||p.evidence_level===evidence)&&(!query||[p.name,p.category,p.market_orientation_unverified,p.notes,...p.proposed_capabilities].join(' ').toLowerCase().includes(query)));$('providerRows').replaceChildren();$('count').textContent=found.length+' records · select a row to inspect';for(const p of found){const tr=el('tr',undefined,'clickable');tr.tabIndex=0;const td=el('td');td.append(el('b',p.name),el('div',p.record_type.replaceAll('_',' '),'subtle'));if(p.routing_eligibility.startsWith('quarantined'))td.append(el('span','QUARANTINED','tag bad'));tr.append(td);const geo=el('td');geo.append(el('div',p.category),el('small',p.market_orientation_unverified,'subtle'));tr.append(geo);const cp=el('td');p.proposed_capabilities.forEach(c=>cp.append(el('span',c,'tag')));tr.append(cp);const ev=el('td');ev.append(evidenceTag(p.evidence_level));tr.append(ev);tr.append(el('td',p.adapter_id?'Fixture only: '+p.adapter_id:'Proposed only'));tr.onclick=()=>detail(p);tr.onkeydown=e=>{if(e.key==='Enter')detail(p)};$('providerRows').append(tr)}}
function detail(p){$('detailTitle').textContent=p.name;$('detailBody').replaceChildren();const fields=[['Provider ID',p.provider_id],['Family ID',p.family_id],['Record type',p.record_type],['Category',p.category],['Market orientation',p.market_orientation_unverified],['Proposed capabilities',p.proposed_capabilities.join(' / ')],['Capability status',p.capability_claim_status],['Evidence',p.evidence_level],['Sources',p.source_ids.join(', ')||'No detailed source reviewed'],['Reference pointer',p.reference_url],['Pointer status',p.reference_url_status],['HTTP status',String(p.reference_http_status??'not retrieved')],['Final URL',p.reference_final_url||'unknown'],['Page title',p.reference_page_title||'not captured'],['Metadata claim',p.reference_metadata_claim||'not captured'],['API mapping',p.api_wire_status],['Routing',p.routing_eligibility],['Access',p.access_model],['Bank adoption',p.bank_adoption_evidence],['Notes',p.notes]];fields.forEach(([k,v])=>{const r=el('div',undefined,'kv');r.append(el('b',k),el('span',v));$('detailBody').append(r)});$('detail').classList.remove('hidden');$('close').focus()}
$('close').onclick=()=>$('detail').classList.add('hidden');$('detail').onclick=e=>{if(e.target===$('detail'))$('close').click()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('close').click()});['search','category','evidenceFilter'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.tab))});
caps.forEach(c=>{const r=el('tr');r.append(el('td',c.capability),el('td',c.result_family));$('capRows').append(r)});
const aa=[['Sumsub','applicantReviewed reviewResult','RED+RETRY means resubmit, not final rejection'],['Veriff','verification.status / code','Expired and abandoned share 9104; use status text'],['Persona','Inquiry JSON API / event wrapper','Completed is not approved'],['Middesk','Business data.object + review tasks','Approved/rejected are client workflow states'],['Companies House','Company profile','Registry record is not applicant KYC clearance'],['OpenCorporates','results.company','Inactive false does not prove active'],['GLEIF','Single lei-records resource','LEI parents are not natural-person UBOs'],['OpenSanctions','One /match query response','Candidate entities remain unresolved'],['Plaid','/identity/match accounts','Null scores unavailable; no automatic holder edge']];aa.forEach(a=>{const r=el('tr');a.forEach(x=>r.append(el('td',x)));$('adapterRows').append(r)});
sources.forEach(s=>{const d=el('div',undefined,'source');d.append(el('b',s.source_id+' · '+s.provider),el('div',s.evidence_type,'subtle'));const a=el('a',s.url);a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';d.append(a,el('p',s.observations));$('sourceList').append(d)});render();
</script></body></html>'''
PAGE=PAGE.replace('__PROVIDERS__',json.dumps(rows,ensure_ascii=False).replace('</','<\\/')).replace('__CAPS__',json.dumps(caps).replace('</','<\\/')).replace('__SOURCES__',json.dumps(sources).replace('</','<\\/'))
(P/'Catalog_Explorer.html').write_text(PAGE)
print('Created DOCX guide and self-contained HTML explorer')
